#nullable enable // autogenerated

using MVZ2.GameContent.Enemies;
using MVZ2.GameContent.Projectiles;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Buffs;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Enemies
{

    [AutoBuffDefinition(VanillaBuffNames.Enemy.hookshotUser)]
    public class HookshotUserBuff : AIEntityBehaviourBuff
    {
        public HookshotUserBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void UpdateAI(Buff buff, Entity entity)
        {
            switch (entity.State)
            {
                case STATE_WALK:
                    UpdateWalkState(buff, entity);
                    break;
            }
        }
        public override void UpdateLogic(Buff buff, Entity entity)
        {
            base.UpdateLogic(buff, entity);
            entity.SetModelProperty("NoHookshot", !HasHookshot(entity));
            entity.SetModelProperty("NoHookshotHook", IsHooking(entity));

            RemoveHookProjectileIfWithoutGun(buff, entity);
        }
        private void UpdateWalkState(Buff buff, Entity entity)
        {
            if (!HasHookshot(buff))
                return;
            var stateTimer = GetOrCreateStateTimerSeconds(buff, HOOK_COOLDOWN_SECONDS);
            var attackSpeed = entity.GetAttackSpeed();
            if (stateTimer.RunToExpiredAndNotNull(attackSpeed))
            {
                stateTimer.ResetSeconds(HOOK_DETECT_SECONDS);
                if (CheckCanHook(buff, entity))
                {
                    var target = hookDetector.DetectEntityWithTheLeast(entity, static (self, t) =>
                    {
                        return (t.GetCenter() - self.GetCenter()).sqrMagnitude;
                    });
                    if (target.ExistsAndAlive())
                    {
                        FireHookshot(buff, entity, target);
                        stateTimer.ResetSeconds(HOOK_COOLDOWN_SECONDS);
                    }
                }
            }
        }
        private void FireHookshot(Buff buff, Entity entity, Entity target)
        {
            var point = GetHookGunPoint(entity);
            var args = entity.GetShootParams();
            args.spawnParam.EntityParent = entity;
            args.spawnParam.SetProperty(LogicProjectileProps.LOCKED_TARGET_ID, new EntityID(target));
            args.position = point;
            args.velocity = (target.GetCenter() - point).normalized * HOOKSHOT_SPEED;
            args.damage = 0;
            args.projectileID = VanillaProjectileID.hookshot;
            args.soundID = VanillaSoundID.hookshotSet;
            var projectile = entity.ShootProjectile(args);
            SetHookID(buff, new EntityID(projectile));
        }
        private bool CheckCanHook(Buff buff, Entity entity)
        {
            return hookDetector.DetectExists(entity);
        }
        public static Vector3 GetHookGunPoint(Entity entity)
        {
            if (!entity.IsEntityOf(VanillaEnemyID.hookshotDrowned) || !HasHookshot(entity))
                return entity.GetCenter();
            var offset = hookOffset;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static void RemoveHookProjectileIfWithoutGun(Buff buff, Entity entity)
        {
            if (!HasHookshot(buff))
            {
                var hookID = GetHookID(buff);
                var hook = hookID?.GetEntity(entity.Level);
                if (hook.ExistsAndAlive())
                {
                    SetHookID(buff, null);
                    hook.Remove();
                }
            }
        }
        public static bool IsHooking(Entity entity)
        {
            var buff = entity.GetFirstBuff<HookshotUserBuff>();
            if (buff == null)
                return false;
            return GetHookID(buff)?.Exists(entity.Level) ?? false;
        }
        public static void SetStateTimer(Buff buff, FrameTimer timer) => buff.SetProperty(PROP_STATE_TIMER, timer);
        public static FrameTimer? GetStateTimer(Buff buff) => buff.GetProperty<FrameTimer>(PROP_STATE_TIMER);
        public static FrameTimer GetOrCreateStateTimerSeconds(Buff buff, float seconds) => buff.GetOrCreateTimerSeconds(PROP_STATE_TIMER, seconds);

        public static void SetHookID(Buff buff, EntityID? value) => buff.SetProperty(PROP_HOOK_ID, value);
        public static EntityID? GetHookID(Buff buff) => buff.GetProperty<EntityID>(PROP_HOOK_ID);

        public static void SetHasHookshot(Buff buff, bool timer) => buff.SetProperty(PROP_HAS_HOOKSHOT, timer);
        public static bool HasHookshot(Buff buff) => buff.GetProperty<bool>(PROP_HAS_HOOKSHOT);
        public static bool HasHookshot(IBuffTarget target) => target.GetFirstBuffProperty<HookshotUserBuff, bool>(PROP_HAS_HOOKSHOT);

        public static readonly PropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("state_timer");
        public static readonly PropertyMeta<EntityID> PROP_HOOK_ID = new VanillaBuffPropertyMeta<EntityID>("hook_id");
        public static readonly PropertyMeta<bool> PROP_HAS_HOOKSHOT = new VanillaBuffPropertyMeta<bool>("has_hookshot", true);
        private const float HOOK_COOLDOWN_SECONDS = 10f;
        private const float HOOK_DETECT_SECONDS = 1f;
        public const float HOOKSHOT_SPEED = 10;
        private static readonly Detector hookDetector = new HookshotDetector();
        private static readonly Vector3 hookOffset = new Vector3(43, 71, 0);
        public const int STATE_WALK = LogicEnemyStates.WALK;
        public const int STATE_HOOK = VanillaEnemyStates.HOOKSHOT_DROWNED_HOOK;
    }
    public class HookshotDetector : Detector
    {
        protected override Bounds GetDetectionBounds(Entity self)
        {
            var point = HookshotUserBuff.GetHookGunPoint(self);
            var facingLeft = self.IsFacingLeft();
            var sizeX = 80000;
            var sizeY = 160;
            var sizeZ = 32;
            var centerX = point.x + self.GetFacingX() * (sizeX * 0.5f);
            var centerY = point.y;
            var centerZ = point.z;
            return new Bounds(new Vector3(centerX, centerY, centerZ), new Vector3(sizeX, sizeY, sizeZ));
        }
        public override bool ValidateTarget(DetectionParams self, Entity target)
        {
            if (target.IsFloor())
                return false;
            return base.ValidateTarget(self, target);
        }
    }
}
